// DETECT ONLY - this workflow never writes to INVESTORS.
// Reason: a thesis row is not always a field copy. IAN and L'Oreal each describe TWO funds and
// had to be split / restructured by hand; blindly copying the sheet text back would undo that.
// Curated values also never equal the raw sheet text, so a writing job would rewrite and re-flag
// the same rows every night forever. So: detect, flag once, and let the 19:00 re-match apply it.
const ALIAS = {
  'piperserica': 'PiperSireca', 'ricebergvc': 'Riceberg Ventures', 'vertex': 'Vertex Ventures',
  'sianacapital': 'Siana Capital', '247vc': '247 VC Tech Fund', 'swishinvc': 'Swishin Ventures',
  'atomiccapital': 'Atomic Capital', 'cedarhillcapital': 'CedarHill Capital',
  'rainmatterzerodha': 'Rainmatter by Zerodha', 'zerencapital': 'Zeren Capital',
  'lorealventurecapital': "L'Oreal Venture Capital", 'a99vc': 'a99 VC'
};
// Firms deliberately split into several INVESTORS rows - do not try to map them back to one row.
const SPLIT = {
  'ricebergvc': 'Riceberg - sheet text is a pass note; record already says foundational AI only (11 Sep)',
  'thechennaiangels': 'Chennai Angels - sheet text is a pass on Body & Beyond, not a thesis (11 Sep)',
  'araliventures': 'Arali - pass note (stopped B2B marketplaces); handled by dropping those deals (11 Sep)',
  'dexterventures': 'Dexter - the user gave the real sector list on 12 Sep (B2B SaaS, AI, FinTech, Consumer, HealthTech); the sheet still says Sector Agnostic',
  'equentis': 'Equentis - revenue bar (>= 8 Cr booked revenue / ARR, tech-enabled) applied as a rule by the user 11 Sep; the prose will never match a field',
  'iangroup': 'IAN Group (split into Angel Fund + Alpha Fund)',
  'elevationcapital': 'Elevation Capital - split 12 Sep into five partner rows (Shourya healthcare, Pranay consumer/EV/logistics, Shreedhar consumer tech/edtech, Lalit fintech, Akshat deeptech); never map the Thesis rows back to one row',
  'lorealventurecapital': "L'Oreal - record deliberately curated into two verticals; raw sheet text will never match"
};

function s(v) { return String(v == null ? '' : v).trim(); }
function norm(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
function skip(v) { const t = s(v).toLowerCase(); return t === '' || t === 'same as previous'; }
// Compare on MEANING, not characters. Without this, 'deep tech' vs 'Deep tech' and
// '1 cr- 4cr' vs 'INR 1-4 Cr' raise flags every night, and a record that is more complete than
// the sheet ('Nihal Shetty' vs 'Nihal') looks like a change when it is an improvement.
function cmp(x) {
  return s(x).toLowerCase()
    .replace(/\b(and|with|along|the|stages|stage|inr|cr|rs)\b/g, ' ')
    .replace(/[^a-z0-9]/g, '');
}
function toks(x) {
  return s(x).toLowerCase().split(/[^a-z0-9]+/)
    .filter(function (t) { return t.length > 2 && ['and','with','along','the','for','are','they','our','inr','cr','rs','stage','stages','focussed','focused','companies','building','size','cheque'].indexOf(t) < 0; });
}
function same(sheetVal, recVal) {
  const a = cmp(sheetVal), b = cmp(recVal);
  if (!a || !b) { return false; }
  if (a === b || a.indexOf(b) >= 0 || b.indexOf(a) >= 0) { return true; }
  // A curated record is a CONDENSED form of the sheet prose: if every meaningful word already
  // present in the record also appears in the sheet text, nothing new has been said.
  // 'Enterprise tech for BFSI' vs 'enterprise tech companies building for BFSI.' -> same.
  // 'AI, Consumer, D2C, FinTech, SaaS' vs 'Sector agnostic' -> genuinely different.
  const A = toks(sheetVal), B = toks(recVal);
  if (B.length === 0) { return false; }
  const inA = {};
  for (const t of A) { inA[t] = true; }
  return B.every(function (t) { return inA[t]; });
}

const raw = $('Read Thesis correction').all().map(function (i) {
  const o = i.json;
  return Object.keys(o).filter(function (k) { return k !== 'row_number'; }).map(function (k) { return o[k]; });
});
const inv = $('Read INVESTORS').all().map(function (i) { return i.json; });
if (inv.length < 100) { throw new Error('ABORT: INVESTORS returned only ' + inv.length + ' rows'); }
const elog = $input.all().map(function (i) { return i.json; });

let P = null;
for (const r of raw) {
  const idx = r.findIndex(function (c) { return s(c).toLowerCase() === 'sector'; });
  if (idx > 0) { P = { firm: 0, contact: 1, email: 2, sector: idx, stage: idx + 1, cheque: idx + 2 }; break; }
}
if (!P) { throw new Error('ABORT: could not locate the Sector label row - Thesis tab layout changed'); }

const byNorm = {};
for (const r of inv) { byNorm[norm(r.investor)] = r; }

// Only flag once: skip anything already open in ERROR LOG for the same investor.
const open = {};
for (const e of elog) {
  // must cover BOTH flag types - NEW_INVESTOR_ON_THESIS_TAB does not start with 'THESIS'
if (s(e.resolved) === '' && s(e.workflow) === 'THESIS-WATCH') { open[s(e.investor).toLowerCase()] = true; }
}

const today = new Date().toISOString().slice(0, 10);
const out = [];
function flag(investor, type, details) {
  if (open[investor.toLowerCase()]) { return; }
  open[investor.toLowerCase()] = true;
  out.push({ json: { timestamp: today, workflow: 'THESIS-WATCH', deal_id: '', startup: '',
                     investor: investor, error_type: type, details: details, resolved: '' } });
}

for (const r of raw) {
  const firm = s(r[P.firm]);
  if (!firm || firm.toLowerCase() === 'firm name') { continue; }
  const key = norm(firm);

  if (SPLIT[key]) { continue; }   // already restructured by hand

  // Exact, then alias, then prefix: the sheet often writes a shortened firm name
  // ('DSG Consumer' for 'DSG Consumer Partners'). Without this it looks like a NEW investor
  // and a re-match run would create a duplicate row for a firm that already exists.
  let t = byNorm[key] || (ALIAS[key] ? byNorm[norm(ALIAS[key])] : null);
  if (!t && key.length >= 6) {
    const cand = Object.keys(byNorm).filter(function (n) { return n.indexOf(key) === 0 || key.indexOf(n) === 0; });
    if (cand.length === 1) { t = byNorm[cand[0]]; }
  }
  if (!t) {
    // Every firm on the corrections sheet already exists in INVESTORS (confirmed 2026-09-08).
    // So a non-match is ALWAYS a naming problem, never a new investor. Creating a row here
    // would duplicate an existing firm under a shortened name.
    flag(firm, 'INVESTOR_NAME_NOT_MATCHED', 'Firm on the Thesis tab did not resolve to an INVESTORS row. It DOES exist - find the correct existing row and add an alias. Do NOT create a new investor row.');
    continue;
  }
  if (s(t.do_not_contact).toLowerCase() === 'yes') { continue; }

  const diffs = [];
  const pairs = [['contact_person', r[P.contact]], ['email', r[P.email]],
                 ['sector', r[P.sector]], ['stage', r[P.stage]], ['cheque_inr_cr', r[P.cheque]]];
  for (const p of pairs) {
    const k = p[0], v = s(p[1]);
    if (skip(v)) { continue; }
    if (same(v, t[k])) { continue; }
    diffs.push(k + ': sheet="' + v.slice(0, 90) + '" vs sheet_record="' + s(t[k]).slice(0, 60) + '"');
  }
  if (diffs.length > 0) {
    flag(s(t.investor), 'THESIS_CHANGE_PENDING', diffs.join(' | ').slice(0, 900));
  }
}

if (out.length === 0) { return []; }
if (out.length > 25) { throw new Error('ABORT: ' + out.length + ' flags exceeds guard of 25'); }
return out;

// FULL-ROW check (user 17 Sep): firms rewrite their thesis in place on the same row (e.g. Piper Serica),
// in ANY column (sector, stage, cheque, geography, ARR, notes). Compare every Thesis-tab row with yesterday's
// snapshot and flag each changed / new / removed row once; the snapshot is then rolled forward.
function s(v) { return String(v == null ? '' : v).replace(/\s+/g, ' ').trim(); }
const grid = $('GET thesis raw').first().json.values || [];
if (grid.length < 5) { throw new Error('ABORT: Thesis tab read only ' + grid.length + ' rows'); }
const snap = (($('GET snapshot').first().json.values) || []).slice(1).filter(function (r) { return s(r[0]); });
if (!snap.length) { throw new Error('ABORT: THESIS SNAPSHOT is empty - write a baseline first'); }
const today = new Date(Date.now() + 330 * 60000).toISOString().slice(0, 10);
const values = [['sheet_row', 'firm', 'row_text', 'snapshot_date']];
const cur = {}; let firm = '';
for (let i = 0; i < grid.length; i++) {
  const cells = (grid[i] || []).map(s); while (cells.length && !cells[cells.length - 1]) { cells.pop(); }
  if (!cells.length) { continue; }
  if (cells[0]) { firm = cells[0]; }
  const text = s(cells.join(' | ')).slice(0, 45000);
  cur[String(i + 1)] = { firm: firm, text: text };
  values.push([String(i + 1), firm, text, today]);
}
while (values.length < 600) { values.push(['', '', '', '']); }
const old = {}; snap.forEach(function (r) { old[s(r[0])] = { firm: s(r[1]), text: s(r[2]) }; });
const flags = [];
function flag(firmName, type, details) { flags.push([today, 'THESIS-WATCH', '', '', firmName, type, details.slice(0, 1800), '']); }
const TODO = ' -> Re-check this firm: update its INVESTORS row AND its INVESTOR_CRITERIA row (sector codes incl. exclusions, business model, stage, cheque, ARR bar, geography). Refine broad words (e.g. consumer) from the fund website + portfolio. Mark resolved when done.';
Object.keys(cur).forEach(function (k) {
  if (!old[k]) { flag(cur[k].firm, 'THESIS_ROW_NEW', 'Thesis tab row ' + k + ' is new. NOW: ' + cur[k].text.slice(0, 900) + TODO); }
  else if (old[k].text !== cur[k].text) { flag(cur[k].firm, 'THESIS_ROW_CHANGED', 'Thesis tab row ' + k + ' was edited. NOW: ' + cur[k].text.slice(0, 900) + ' | WAS: ' + old[k].text.slice(0, 500) + TODO); }
});
Object.keys(old).forEach(function (k) { if (!cur[k]) { flag(old[k].firm, 'THESIS_ROW_REMOVED', 'Thesis tab row ' + k + ' is now blank. WAS: ' + old[k].text.slice(0, 900) + ' -> check whether the firm moved rows or the correction was withdrawn.'); } });
if (flags.length > 40) {
  return [{ json: { ok: false, values: [], flags: [[today, 'THESIS-WATCH', '', '', 'Thesis correction tab', 'THESIS_TAB_LAYOUT_CHANGED', flags.length + ' rows differ from the snapshot (rows inserted, deleted or re-sorted?). Snapshot NOT rolled forward. Compare the tab by firm name by hand, apply real changes, then re-baseline THESIS SNAPSHOT.', '']] } }];
}
return [{ json: { ok: true, values: values, flags: flags } }];

